42	// ── SHA-256 hash helper ───────────────────────────────────────
43	
44	async function sha256Hex(input: string): Promise<string> {
45	  const encoded = new TextEncoder().encode(input);
46	  const hashBuffer = await crypto.subtle.digest("SHA-256", encoded);
47	  const hashArray = Array.from(new Uint8Array(hashBuffer));
48	  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
49	}
