107	// Filter findings: remove premium ones if the scan was on a free plan
108	// Since we don't know the plan here, we expose all non-premium findings
109	// Premium findings have ai_suggestion blurred on the client side anyway
110	function sanitizeResults(results: ScanResultRow[]): ScanResultRow[] {
111	  return results.map((r) => ({
