133	    return corsResponse({ error: "Missing token" }, 400);
134	  }
135	
136	  const supabaseUrl = Deno.env.get("SUPABASE_URL");
137	  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
138	
139	  if (!supabaseUrl || !serviceKey) {
140	    return corsResponse({ error: "Server configuration error" }, 500);
141	  }
142	
143	  // Use service_role client to bypass RLS
144	  const adminClient = createClient(supabaseUrl, serviceKey, {
145	    auth: { persistSession: false },
146	  });
147	
148	  // Fetch scan by share_token
149	  const { data: scanData, error: scanError } = await adminClient
150	    .from("scans")
151	    .select("*")
152	    .eq("share_token", token)
153	    .eq("is_public", true)
154	    .maybeSingle();
155	
156	  if (scanError) {
157	    return corsResponse({ error: "Database error" }, 500);
158	  }
159	
160	  if (!scanData) {
161	    return corsResponse({ error: "Report not found or no longer public" }, 404);
162	  }
163	
164	  const scan = scanData as ScanRow;
165	
166	  // Fetch scan results
167	  const { data: resultsData, error: resultsError } = await adminClient
168	    .from("scan_results")
169	    .select("*")
170	    .eq("scan_id", scan.id);
171	
172	  if (resultsError) {
173	    return corsResponse({ error: "Failed to load report results" }, 500);
174	  }
175	
176	  const results = (resultsData ?? []) as ScanResultRow[];
177	
178	  // ── Fetch team branding if scan belongs to a team ─────────────
179	  let teamBranding: TeamBranding | null = null;
180	
181	  if (scan.team_id) {
182	    const { data: teamData, error: teamError } = await adminClient
183	      .from("teams")
184	      .select("id, name, logo_url, brand_color, custom_domain")
185	      .eq("id", scan.team_id)
186	      .maybeSingle();
187	
188	    if (!teamError && teamData) {
189	      const team = teamData as TeamRow;
190	      teamBranding = {
191	        name: team.name,
192	        logo_url: team.logo_url,
193	        brand_color: team.brand_color,
194	        custom_domain: team.custom_domain,
195	      };
196	    }
197	    // Non-fatal: if team fetch fails, fall back to no branding
198	  }
199	
200	  return corsResponse({
201	    scan: sanitizeScan(scan),
202	    results: sanitizeResults(results),
203	    ...(teamBranding ? { teamBranding } : {}),
204	  });
205	});
